CREATE TYPE kyc_status AS ENUM ('pending','verified','rejected');
CREATE TYPE account_kind AS ENUM ('wallet','cash_in','cash_out','fee_revenue');
CREATE TYPE transfer_type AS ENUM ('top_up','peer','withdrawal','fee','reversal');
CREATE TYPE transfer_status AS ENUM ('held','posted','reversed','failed');
CREATE TYPE entry_direction AS ENUM ('debit','credit');
CREATE TABLE users (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,phone TEXT NOT NULL UNIQUE,kyc_status kyc_status NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE accounts (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,owner_user_id BIGINT REFERENCES users(id),account_kind account_kind NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'INR' CHECK(currency='INR'),balance_paise BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK((account_kind='wallet')=(owner_user_id IS NOT NULL)),CHECK(account_kind='wallet' OR balance_paise IS NOT NULL));
CREATE UNIQUE INDEX one_system_account_per_kind ON accounts(account_kind) WHERE owner_user_id IS NULL;
CREATE TABLE transfers (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,type transfer_type NOT NULL,status transfer_status NOT NULL,amount_paise BIGINT NOT NULL CHECK(amount_paise>0),created_by BIGINT NOT NULL REFERENCES users(id),reversal_of_id BIGINT UNIQUE REFERENCES transfers(id),note TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ledger_entries (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,transfer_id BIGINT NOT NULL REFERENCES transfers(id),account_id BIGINT NOT NULL REFERENCES accounts(id),direction entry_direction NOT NULL,amount_paise BIGINT NOT NULL CHECK(amount_paise>0),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX statement_entries ON ledger_entries(account_id,created_at DESC,id DESC);
CREATE INDEX transfer_entries ON ledger_entries(transfer_id);
CREATE TABLE idempotency_keys (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),key UUID NOT NULL,body_hash CHAR(64) NOT NULL,status TEXT NOT NULL CHECK(status IN ('processing','completed')),response_code INTEGER,response_body JSONB,completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,key));
CREATE TABLE transfer_status_audits (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,transfer_id BIGINT NOT NULL REFERENCES transfers(id),old_status transfer_status,new_status transfer_status NOT NULL,changed_by BIGINT REFERENCES users(id),changed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE risk_rules (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,code TEXT UNIQUE NOT NULL,threshold_paise BIGINT NOT NULL CHECK(threshold_paise>0),enabled BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE risk_flags (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,transfer_id BIGINT NOT NULL REFERENCES transfers(id),rule_code TEXT NOT NULL,label TEXT NOT NULL,explanation TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE job_locks (name TEXT PRIMARY KEY); INSERT INTO job_locks VALUES ('reconciliation');
CREATE TABLE reconciliation_runs (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,started_at TIMESTAMPTZ NOT NULL DEFAULT now(),ended_at TIMESTAMPTZ,status TEXT NOT NULL,problem_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE reconciliation_problems (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,run_id BIGINT NOT NULL REFERENCES reconciliation_runs(id),check_name TEXT NOT NULL,entity_id TEXT,expected TEXT,actual TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE FUNCTION immutable_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'ledger entries are immutable'; END; $$;
CREATE TRIGGER immutable_ledger_entries BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_ledger();
CREATE FUNCTION reject_overdraft() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.account_kind='wallet' AND NEW.balance_paise<0 THEN RAISE EXCEPTION 'wallet balance cannot be negative'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER no_wallet_overdraft BEFORE INSERT OR UPDATE OF balance_paise ON accounts FOR EACH ROW EXECUTE FUNCTION reject_overdraft();
INSERT INTO accounts(account_kind) VALUES ('cash_in'),('cash_out'),('fee_revenue');
INSERT INTO risk_rules(code,threshold_paise) VALUES ('high_value',10000000);
